package com.fiap.sast.web;
import com.fiap.sast.analysis.*; import com.fiap.sast.github.GitHubClient; import com.fiap.sast.persistence.*; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.http.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.net.URI; import java.util.*;
@RestController @RequestMapping("/api/analyses") public class AnalysisController { private final GitHubClient git; private final SastEngine engine; private final AnalysisRepository repo; public AnalysisController(GitHubClient g,SastEngine e,AnalysisRepository r){git=g;engine=e;repo=r;} public record Request(@NotBlank String repositoryUrl,String reference){}
 @PostMapping @Transactional public ResponseEntity<Analysis> create(@Valid @RequestBody Request request){var s=git.download(request.repositoryUrl(),request.reference());if(s.files().isEmpty())throw new Unprocessable();var a=new Analysis();a.repositoryUrl=s.url();a.repositoryOwner=s.owner();a.repositoryName=s.repo();a.reference=s.reference();a.filesAnalyzed=s.files().size();s.files().forEach(f->engine.analyze(f.content(),f.path()).forEach(x->{var y=new Finding();y.analysis=a;y.ruleId=x.ruleId();y.title=x.title();y.severity=x.severity();y.cwe=x.cwe();y.description=x.description();y.fileName=x.fileName();y.line=x.line();y.column=x.column();y.snippet=x.snippet();a.findings.add(y);}));repo.save(a);return ResponseEntity.created(URI.create("/api/analyses/"+a.id)).body(a);}
 @GetMapping("/{id}") public Analysis get(@PathVariable UUID id){return repo.findById(id).orElseThrow(NoSuchElementException::new);} public static class Unprocessable extends RuntimeException{} }
